// 2D DP：dp[i][j] = s 前 i 字是否能被 p 前 j 字匹配
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)
function isMatch(s, p) {
    const m = s.length, n = p.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(false));
    dp[0][0] = true;
    const match = (i, j) => p[j - 1] === '.' || s[i - 1] === p[j - 1];
    for (let i = 0; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (p[j - 1] === '*') {
                dp[i][j] = dp[i][j - 2] // x* 匹配 0 次
                    || (i > 0 && match(i, j - 1) && dp[i - 1][j]); // x* 再多吃一個字元
            }
            else {
                dp[i][j] = i > 0 && match(i, j) && dp[i - 1][j - 1];
            }
        }
    }
    return dp[m][n];
}

