class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        """
        方法：動態規劃
        時間複雜度: O(m * n)
        空間複雜度: O(m * n)
        """
        m, n = len(s), len(p)

        # dp[i][j]: s 的前 i 個字元與 p 的前 j 個字元是否匹配
        dp = [[False] * (n + 1) for _ in range(m + 1)]

        # 初始化：空字串匹配空模式
        dp[0][0] = True

        # 初始化：空字串匹配 x* 模式
        for j in range(2, n + 1):
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 2]

        # 填充 DP 表格
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if p[j - 1] == '*':
                    # 情況 1: 匹配 0 次（忽略 x*）
                    dp[i][j] = dp[i][j - 2]

                    # 情況 2: 匹配 1+ 次
                    if s[i - 1] == p[j - 2] or p[j - 2] == '.':
                        dp[i][j] = dp[i][j] or dp[i - 1][j]
                else:
                    # 普通字元或 '.'
                    if s[i - 1] == p[j - 1] or p[j - 1] == '.':
                        dp[i][j] = dp[i - 1][j - 1]

        return dp[m][n]

