class Solution {
    /**
     * 方法：動態規劃
     * 時間複雜度: O(m * n)
     * 空間複雜度: O(m * n)
     */
    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();

        // dp[i][j]: s 的前 i 個字元與 p 的前 j 個字元是否匹配
        boolean[][] dp = new boolean[m + 1][n + 1];

        // 初始化：空字串匹配空模式
        dp[0][0] = true;

        // 初始化：空字串匹配 x* 模式
        for (int j = 2; j <= n; j++) {
            if (p.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 2];
            }
        }

        // 填充 DP 表格
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (p.charAt(j - 1) == '*') {
                    // 情況 1: 匹配 0 次（忽略 x*）
                    dp[i][j] = dp[i][j - 2];

                    // 情況 2: 匹配 1+ 次
                    if (s.charAt(i - 1) == p.charAt(j - 2) || p.charAt(j - 2) == '.') {
                        dp[i][j] = dp[i][j] || dp[i - 1][j];
                    }
                } else {
                    // 普通字元或 '.'
                    if (s.charAt(i - 1) == p.charAt(j - 1) || p.charAt(j - 1) == '.') {
                        dp[i][j] = dp[i - 1][j - 1];
                    }
                }
            }
        }

        return dp[m][n];
    }
}

