// 2D DP：dp[i][j] = s 前 i 字是否能被 p 前 j 字匹配
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)
bool isMatch(char* s, char* p) {
    int m = strlen(s), n = strlen(p);
    bool* dp = calloc((m + 1) * (n + 1), sizeof(bool));
    #define DP(i, j) dp[(i) * (n + 1) + (j)]
    #define MATCH(i, j) (p[(j) - 1] == '.' || s[(i) - 1] == p[(j) - 1])
    DP(0, 0) = true;

    for (int i = 0; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (p[j - 1] == '*') {
                DP(i, j) = DP(i, j - 2)                              // x* 匹配 0 次
                    || (i > 0 && MATCH(i, j - 1) && DP(i - 1, j));   // x* 再多吃一個字元
            } else {
                DP(i, j) = i > 0 && MATCH(i, j) && DP(i - 1, j - 1);
            }
        }
    }
    bool ans = DP(m, n);
    #undef DP
    #undef MATCH
    free(dp);
    return ans;
}
